const mode=document.getElementById('mode'),teacher=document.getElementById('teacher'),learner=document.getElementById('learner'),panels=[...document.querySelectorAll('.task')],tabs=[...document.querySelectorAll('[data-step]')],prev=document.querySelector('.prev'),next=document.querySelector('.next'),statusEl=document.getElementById('status'),title=document.getElementById('title'),desc=document.getElementById('desc');let current=0;
function showPage(i,focus=false){current=i;panels.forEach((p,j)=>p.hidden=j!==i);tabs.forEach((b,j)=>{if(i===j)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});prev.disabled=i===0;next.hidden=i===3;statusEl.textContent='Schritt '+(i+1)+' von 4';if(focus)panels[i].querySelector('h2').focus({preventScroll:true});}
function teacherMode(on){teacher.hidden=!on;learner.hidden=on;mode.textContent=on?'Zum Arbeitsauftrag':'Für die Lehrperson';title.textContent=on?'Unterrichtsvorbereitung':'Einen eigenen Beat bauen';desc.textContent=on?'Ableton Learning Music – Erste Schritte und Beats':'Sie brauchen Ihren Laptop und Kopfhörer. Am Schluss spielen Sie jemandem Ihren Beat vor.';if(!on)document.querySelectorAll('audio').forEach(a=>a.pause());}
function route(focus=false){let h=location.hash;const on=h==='#lehrperson';teacherMode(on);if(!on){let n=Number(h.replace('#schritt',''));showPage(n>=1&&n<=4&&Number.isInteger(n)?n-1:0,focus)}}
function step(i){if(i>=0&&i<4)location.hash='schritt'+(i+1)}
tabs.forEach((b,i)=>b.addEventListener('click',()=>step(i)));prev.onclick=()=>step(current-1);next.onclick=()=>step(current+1);mode.onclick=()=>{location.hash=teacher.hidden?'lehrperson':'schritt'+(current+1)};window.addEventListener('hashchange',()=>route(true));document.querySelectorAll('audio').forEach(a=>a.addEventListener('play',()=>document.querySelectorAll('audio').forEach(b=>{if(a!==b)b.pause()})));route();
let printOpen=false;window.addEventListener('beforeprint',()=>{if(!teacher.hidden){const d=teacher.querySelector('details');printOpen=d.open;d.open=true;}});window.addEventListener('afterprint',()=>{if(!teacher.hidden)teacher.querySelector('details').open=printOpen;});
